		List<String> list;
		int index;
		int max;
		Obj(List<String> list){
			this.list = list;
			this.index = 0;
			this.max = list.size();
		}
		boolean hasNext(){
			return this.index < this.max;
		}
		String next(){
			if(this.hasNext()){
				return this.list.get(this.index++);
			}else{
				throw new RuntimeException("ArrayIndexOutOfBoundsException ‚There is no more input");
			}
		}
	}

